  const { result } = renderHook(() => useResizeObserver());
  expect(result.current.width).toBe(0);
  expect(result.current.height).toBe(0);
});

test('returns a ref object', () => {
  const { result } = renderHook(() => useResizeObserver());
  expect(result.current.ref).toHaveProperty('current');
