test('calls ResizeObserver constructor when ref is attached', () => {
  const observeSpy = vi.fn();
  const disconnectSpy = vi.fn();
  vi.stubGlobal('ResizeObserver', vi.fn(() => ({ observe: observeSpy, disconnect: disconnectSpy })));
  const el = document.createElement('div');
  const { result, unmount } = renderHook(() => useResizeObserver());
  act(() => { result.current.ref.current = el; });
  unmount();
  vi.unstubAllGlobals();
});

test('updates size from ResizeObserver entry', () => {
  let cb: ResizeObserverCallback;
  vi.stubGlobal('ResizeObserver', vi.fn((fn: ResizeObserverCallback) => {
    cb = fn;
    return { observe: vi.fn(), disconnect: vi.fn() };
  }));
  const { result } = renderHook(() => useResizeObserver());
  act(() => {
    cb([{ contentRect: { width: 300, height: 150 } }] as any, {} as any);
  });
  expect(result.current.width).toBe(300);
  expect(result.current.height).toBe(150);
  vi.unstubAllGlobals();
});

